import os, json
import numpy as np

T = 32

# Deep utilities
def _find_first_len32_array(obj):
    # DFS to find first list/tuple length 32 of numbers
    if isinstance(obj, (list, tuple)) and len(obj) == T and all(isinstance(x, (int, float)) for x in obj):
        return np.array(obj, dtype=float)
    if isinstance(obj, dict):
        for v in obj.values():
            arr = _find_first_len32_array(v)
            if arr is not None:
                return arr
    if isinstance(obj, (list, tuple)):
        for v in obj:
            arr = _find_first_len32_array(v)
            if arr is not None:
                return arr
    return None

def _extract_gamma(obj):
    # try common keys first
    for k in ("gamma", "gamma_profile", "gamma_t", "gamma_values"):
        if k in obj:
            arr = _find_first_len32_array(obj[k])
            if arr is not None:
                return arr
    # nested fallback
    return _find_first_len32_array(obj)

def _extract_per_condition(obj):
    # Accept various container keys
    cand = None
    for k in (
        "per_condition_step_mae",
        "val_mae_by_condition",
        "per_condition_mae",
        "condition_step_mae",
        "conditions",
        "by_condition",
    ):
        if k in obj and isinstance(obj[k], dict):
            cand = obj[k]
            break
    if cand is None:
        # If not present, maybe whole object is the condition map
        if isinstance(obj, dict):
            cand = obj
        else:
            return {}
    out = {}
    # Each value may be a length-32 list, or nested where we need to find first length-32 array
    for ck, cv in cand.items():
        arr = _find_first_len32_array(cv)
        if arr is not None and arr.size == T and not np.isnan(arr).any():
            out[str(ck)] = arr
    return out

def test():
    base_dir = "storage/ariadne/analyses"
    gamma_list = []
    percond_list = []

    for root, _, files in os.walk(base_dir):
        for fn in files:
            if not fn.endswith(".json"):
                continue
            path = os.path.join(root, fn)
            try:
                with open(path, "r") as f:
                    obj = json.load(f)
            except Exception:
                continue
            g = _extract_gamma(obj)
            if g is not None and g.size == T:
                gamma_list.append((path, g))
            pc = _extract_per_condition(obj)
            if pc:
                percond_list.append((path, pc))

    summary = {
        "gamma_files": len(gamma_list),
        "per_condition_files": len(percond_list),
        "base_dir": base_dir,
    }

    if not gamma_list or not percond_list:
        out = {"ok": False, "reason": "Insufficient files after deep scan", **summary}
    else:
        G = np.vstack([g for _, g in gamma_list])
        gamma_mean = G.mean(axis=0)
        gamma_std  = G.std(axis=0)

        # Merge per-condition
        cond_acc = {}
        for _, pc in percond_list:
            for ck, arr in pc.items():
                cond_acc.setdefault(ck, []).append(arr)
        cond_stats = {}
        for ck, lst in cond_acc.items():
            M = np.vstack(lst)
            if M.shape[1] != T or np.isnan(M).any():
                continue
            cond_stats[ck] = {
                "mean": M.mean(axis=0).tolist(),
                "std":  M.std(axis=0).tolist(),
                "count": int(M.shape[0]),
            }

        # Overall step difficulty
        if cond_stats:
            step_mae_mean = np.vstack([np.array(v["mean"]) for v in cond_stats.values()]).mean(axis=0)
        else:
            step_mae_mean = np.full((T,), np.nan)

        def safe_corr(a, b):
            a = np.asarray(a, dtype=float); b = np.asarray(b, dtype=float)
            if np.isnan(a).any() or np.isnan(b).any(): return None
            if a.std() == 0 or b.std() == 0: return None
            return float(np.corrcoef(a, b)[0,1])

        corr_gamma_vs_mean = safe_corr(gamma_mean, step_mae_mean)

        # heuristic potential alignment score
        def z(x): x=np.asarray(x,dtype=float); return (x-x.mean())/(x.std()+1e-8)
        potential = None if np.isnan(step_mae_mean).any() else float(np.dot(-z(gamma_mean), z(step_mae_mean))/T)

        out = {
            "ok": True,
            **summary,
            "gamma_mean": gamma_mean.tolist(),
            "gamma_std": gamma_std.tolist(),
            "corr_gamma_vs_step_mae_mean": corr_gamma_vs_mean,
            "potential_alignment_score": potential,
            "conditions_analyzed": {k: {"count": v["count"]} for k,v in cond_stats.items()},
        }

    out_path = os.path.join(base_dir, "cond_gamma_correlation_v3.json")
    with open(out_path, "w") as f:
        json.dump(out, f, indent=2)
    print("Analysis v3 complete ->", out_path)
    return "OK"
